{"command": "cd /workspace && cat > work/pitch.py <<'EOF'
import numpy as np, wave
def read(path):
    w=wave.open(path); n=w.getnframes(); sr=w.getframerate(); ch=w.getnchannels(); sw=w.getsampwidth()
    raw=w.readframes(n)
    if sw==2: d=np.frombuffer(raw,dtype='<i2').astype(np.float32)
    elif sw==1: d=(np.frombuffer(raw,dtype=np.uint8).astype(np.float32)-128)
    else: raise Exception('sw')
    if ch==2: d=d.reshape(-1,2).mean(1)
    return d/32768.0, sr
def f0(d, sr, lo=20.0, hi=3000.0, win=1.0):
    # autocorrelation based F0, robust to harmonics
    n=int(win*sr)
    best=None
    for start in range(0, len(d)-n, n//2):
        seg=d[start:start+n]
        if np.sqrt((seg**2).mean())<1e-4: continue
        seg=seg-seg.mean()
        ac=np.correlate(seg,seg,'full')[len(seg)-1:]
        ac/=ac[0]
        lag_lo=int(sr/hi); lag_hi=int(sr/lo)
        acw=ac[lag_lo:lag_hi]
        if len(acw)==0: continue
        thr=0.6*np.max(acw)
        # first lag where ac>thr (rising through)
        idx=None
        for i in range(1,len(acw)):
            if acw[i]>thr and acw[i]>=acw[i-1]:
                idx=i; break
        if idx is None: idx=int(np.argmax(acw))
        lag=idx+lag_lo
        # parabolic refine
        if 0<lag<len(ac)-1:
            y0,y1,y2=ac[lag-1],ac[lag],ac[lag+1]
            den=(y0-2*y1+y2)
            off=0.5*(y0-y2)/den if den!=0 else 0
            lag=lag+off
        f=sr/lag
        if best is None or np.max(acw)>best[1]: pass
        if best is None: best=(f,np.max(acw))
        else:
            if np.max(acw)>best[1]: best=(f,np.max(acw))
    return best
EOF
