    # stereo: read() already averaged channels! need raw
    return None
import wave
def lr(path='work/probe.wav',a=1,b=5):
    w=wave.open(path); ch=w.getnchannels(); d=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(np.float32)/32768
    if ch==2: d=d.reshape(-1,2)
    else: d=np.stack([d,d],1)
    sr=w.getframerate(); seg=d[int(a*sr):int(b*sr)]
    return float(np.sqrt((seg[:,0]**2).mean())), float(np.sqrt((seg[:,1]**2).mean()))
def peakf(a=1,b=5):
    d,sr=read('work/probe.wav'); seg=d[int(a*sr):int(b*sr)]*np.hanning(int((b-a)*sr))
    S=np.abs(np.fft.rfft(seg)); f=np.fft.rfftfreq(len(seg),1/sr); return round(float(f[np.argmax(S)]),2)
def rms(a=1,b=5):
    d,sr=read('work/probe.wav'); return float(np.sqrt((d[int(a*sr):int(b*sr)]**2).mean()))
def setc(**kw): return {"name":"pattern_set_cell","arguments":dict({"pattern":0,"row":0,"channel":3,"note":"C-4","instrument":1,"volume":80},**kw)}
batch([{"name":"cell_clear","arguments":{"pattern":0,"row":r,"channel":3}} for r in range(64)])
