{"command": "cat > /workspace/work/gen_song.py <<'PYEOF'
import json, sys
sys.path.insert(0,'work')
from setup import setup_calls

NAMES=['C-','C#','D-','D#','E-','F-','F#','G-','G#','A-','A#','B-']
def nn(pc,oct_): 
    pc%=12; return f"{NAMES[pc]}{oct_}"
def tr(name,semi):
    letter=name[:2]; octv=int(name[2:])
    pc=NAMES.index(letter)
    v=pc+octv*12+semi
    return NAMES[v%12]+str(v//12)

# ---------------- harmony ----------------
CH={
 'Am':{'bass':'A-2','arp':['A-3','C-4','E-4','A-4'],'org':('E-4','A-4'),'pad':('E-3','A-3')},
 'F' :{'bass':'F-2','arp':['F-3','A-3','C-4','F-4'],'org':('F-4','A-4'),'pad':('F-3','A-3')},
 'C' :{'bass':'C-3','arp':['C-4','E-4','G-4','C-5'],'org':('E-4','G-4'),'pad':('E-3','G-3')},
 'G' :{'bass':'G-2','arp':['G-3','B-3','D-4','G-4'],'org':('D-4','G-4'),'pad':('D-3','G-3')},
 'Em':{'bass':'E-2','arp':['E-3','G-3','B-3','E-4'],'org':('E-4','G-4'),'pad':('E-3','G-3')},
 'Dm':{'bass':'D-2','arp':['D-4','F-4','A-4','D-5'],'org':('F-4','A-4'),'pad':('F-3','A-3')},
 'E' :{'bass':'E-2','arp':['E-3','G#3','B-3','E-4'],'org':('E-4','G#4'),'pad':('E-3','G#3')},
}
PAT_CH={
 0:['Am','F','C','G'], 1:['Am','F','C','G'], 2:['Am','F','C','G'], 3:['Am','F','C','G'],
 4:['Am','F','C','G'], 5:['Am','F','C','G'],
 6:['F','C','G','Am'], 7:['F','C','G','E'], 8:['F','C','G','Am'], 9:['F','G','Am','E'],
 10:['Am','Em','F','G'], 11:['C','G','Dm','E'],
 12:['Am','F','C','G'], 13:['Am','F','C','G'], 14:['Am','F','G','Am'],
}
# channels
KICK,SNARE,HATC,HATO,BASS,ORG1,ORG2,ARP,LEAD,LEAD2 = range(10)
I_KICK,I_SNARE,I_HATC,I_HATO,I_CRASH,I_TOM,I_RISER = 1,2,3,4,5,6,7
I_BASS,I_ORG1,I_ORG2,I_ARP,I_LEAD,I_LEAD2,I_PAD1,I_PAD2 = 8,9,10,11,12,13,14,15

C=[]   # batch calls
def add(ch,pat,row,note=None,inst=None,vol=None,fx=None,fp=None):
    a={"pattern":pat,"row":row,"channel":ch}
    if note is not None: a["note"]=note
    if inst is not None: a["instrument"]=inst
    if vol is not None: a["volume"]=vol+16
    if fx is not None: a["effect"]=fx
    if fp is not None: a["effect_param"]=fp
    C.append({"name":"pattern_set_cell","arguments":a})
def clear(ch,pat,r0=0,r1=64):
    for r in range(r0,r1): C.append({"name":"cell_clear","arguments":{"pattern":pat,"row":r,"channel":ch}})

def fx_cut(row_len=6, tick=4):   # note cut for staccato (speed 6)
    return (12, tick)

# ---------------- drums ----------------
GR_A={'kick':[0,6,8,14],'snare':[4,12],'hatc':[0,2,4,8,10,12],'hato':[6,14]}
GR_B={'kick':[0,6,8,11,14],'snare':[4,12],'hatc':[0,2,4,8,10,12],'hato':[6,14]}
def drums(pat,bar,gr,vol=64,hat16=False,ghost=False):
    b=bar*16
    for r in gr['kick']: add(KICK,pat,b+r,I_KICK and 'C-4',I_KICK,vol)
    for r in gr['snare']: add(SNARE,pat,b+r,'C-4',I_SNARE,vol)
    for r in gr['hatc']: add(HATC,pat,b+r,'C-4',I_HATC,int(vol*0.62))
    if hat16:
        for r in range(16):
            if r not in gr['hatc'] and r not in gr['hato']:
                add(HATC,pat,b+r,'C-4',I_HATC,int(vol*0.30))
    for r in gr['hato']: add(HATO,pat,b+r,'C-4',I_HATO,int(vol*0.60))
    if ghost:
        for r in (7,15): add(SNARE,pat,b+r,'C-4',I_SNARE,20)
def fill_snare(pat,bar,rows=(12,13,14,15),vols=(34,44,54,64)):
    b=bar*16
    for r,v in zip(rows,vols): add(SNARE,pat,b+r,'C-4',I_SNARE,v)
def fill_toms(pat,bar):
    b=bar*16
    for i,(r,pc) in enumerate([(8,'C-4'),(9,'C-4'),(10,'B-3'),(11,'B-3'),(12,'A-3'),(13,'A-3')]):
        add(SNARE,pat,b+r,pc,I_TOM,46+i*3)
    fill_snare(pat,bar,(14,15),(54,64))
def roll(pat,r0,r1,inst=I_SNARE,v0=18,v1=64):
    n=r1-r0
    for i,r in enumerate(range(r0,r1)):
        v=int(v0+(v1-v0)*i/max(1,n-1))
        add(SNARE,pat,r,'C-4',inst,v)

# ---------------- bass ----------------
def bass_bar(pat,bar,root,style='16'):
    b=bar*16
    if style=='16':
        for r in range(16):
            n=root
            if r in (6,14): n=tr(root,12)
            elif r in (7,15): n=tr(root,7)
            add(BASS,pat,b+r,n,I_BASS,64,12,4)
    elif style=='8':
        for r in range(0,16,2):
            n=root
            if r in (6,14): n=tr(root,12)
            add(BASS,pat,b+r,n,I_BASS,64,12,4)
    elif style=='hold':
        add(BASS,pat,b,root,I_BASS,52)
def bass_fill(pat,bar,root):
    b=bar*16
    sc=[0,3,5,7,10,12,15]  # minor run
    for i,r in enumerate([0,2,4,6,8,10,12,14]):
        add(BASS,pat,b+r,tr(root,[0,0,0,0,0,0,0,0][i]+ (12 if i%4==3 else 0)),I_BASS,64,12,4)

# ---------------- arp ----------------
ARPSEQ=[0,1,2,3,2,1,2,3]
def arp_bar(pat,bar,notes,div=16,vol=36,seq=None):
    b=bar*16; seq=seq or ARPSEQ
    if div==16:
        for r in range(16): add(ARP,pat,b+r,notes[seq[r%len(seq)]],I_ARP,vol,12,4)
    else:
        for i,r in enumerate(range(0,16,2)): add(ARP,pat,b+r,notes[seq[i%len(seq)]],I_ARP,vol,12,5)
def arp_hold(pat,bar,notes,vol=34):
    b=bar*16
    for i,r in enumerate((0,4,8,12)): add(ARP,pat,b+r,notes[i%len(notes)],I_ARP,vol)

# ---------------- organ ----------------
def org_stab(pat,bar,pair,vol=44):
    b=bar*16
    for r in (2,6,10,14):
        add(ORG1,pat,b+r,pair[0],I_ORG1,vol,12,4)
        add(ORG2,pat,b+r,pair[1],I_ORG2,vol,12,4)
def org_hold(pat,bar,pair,vol=44,inst=(I_ORG1,I_ORG2)):
    b=bar*16
    add(ORG1,pat,b,pair[0],inst[0],vol)
    add(ORG2,pat,b,pair[1],inst[1],vol)

# ---------------- melody ----------------
MEL_A=[(0,'E-5',3),(3,'F-5',1),(4,'A-5',4),(8,'G-5',2),(10,'E-5',2),(12,'D-5',2),(14,'E-5',2),
       (16,'F-5',3),(19,'E-5',1),(20,'F-5',4),(24,'A-5',4),(28,'G-5',2),(30,'F-5',2),
       (32,'E-5',3),(35,'F-5',1),(36,'G-5',4),(40,'E-5',4),(44,'C-5',2),(46,'D-5',2),
       (48,'E-5',3),(51,'D-5',1),(52,'B-4',4),(56,'D-5',3),(59,'E-5',1),(60,'D-5',2),(62,'F-5',2)]
