import numpy as np, math
NAMES=['C-','C#','D-','D#','E-','F-','F#','G-','G#','A-','A#','B-']
def f2n(f):
    m=69+12*math.log2(f/440.0); i=int(round(m))
    return NAMES[i%12]+str(i//12-1)+f'({100*(m-i):+.0f}c)'
